-- 0155 — Six text packs for people everywhere (FR-STK-02, FR-STK-06). Additive only: new pack and sticker rows.
--
-- Product owner, Nov 18: more word-art packs like Corporate, Gen Z and Trentahin that suit international users too.
--
--   Gym, Foodie, Travel, Student, Parents, Fan Life    premium, 30 stickers each, each in its own lettering
--
-- Tags use the onboarding answer keys (gym_clothes, school, classmates, family, family_duties, …) so the shop's
-- "For you" row can match them. Store products (me.pickld.pack.<slug, - as _>) still have to be created in App
-- Store Connect and RevenueCat; until then the shop shows the packs without a price or a Get button (0029).
-- Art: rendered at 2048 px by scripts/render-stickers.mjs (lettering in word-art.mjs) and bundled in stickerArt.ts.
-- Upload with `cd workers/photos && deno task stickers`.

insert into public.sticker_packs (slug, name, tier, store_product_id, sort, description) values
  ('gym', 'Gym', 'premium', 'me.pickld.pack.gym', 23, 'Leg day, rest day, PR day. For the reps nobody sees and the progress you do.'),
  ('foodie', 'Foodie', 'premium', 'me.pickld.pack.foodie', 24, 'Eat first, post later. For brunch dates, street food and the dish you keep coming back to.'),
  ('travel', 'Travel', 'premium', 'me.pickld.pack.travel', 25, 'Out of office, into the world. For airports, road trips and the places you''ll talk about for years.'),
  ('student', 'Student', 'premium', 'me.pickld.pack.student', 26, 'Study hard, nap harder. For exam weeks, group projects and the classmates who get you through.'),
  ('parents', 'Parents', 'premium', 'me.pickld.pack.parents', 27, 'Tired but grateful. For school runs, first steps and the little people who run the house.'),
  ('fan-life', 'Fan Life', 'premium', 'me.pickld.pack.fan_life', 28, 'Bias wrecked, lightstick charged. For concerts, comebacks and the friends you made in the fandom.');

